import { Asset } from "expo-asset";
import * as FileSystem from "expo-file-system";
import { Platform } from "react-native";

let piDigitsCache: string | null = null;

export async function loadPiDigits(): Promise<string> {
  if (piDigitsCache) return piDigitsCache;

  if (Platform.OS === "web") {
    try {
      const asset = Asset.fromModule(require("../assets/pi_digits.txt"));
      await asset.downloadAsync();
      if (asset.localUri) {
        const content = await FileSystem.readAsStringAsync(asset.localUri);
        piDigitsCache = content;
        return content;
      }
    } catch {}

    const fallback =
      "";
    piDigitsCache = fallback;
    return fallback;
  }

  try {
    const asset = Asset.fromModule(require("../assets/pi_digits.txt"));
    await asset.downloadAsync();
    if (asset.localUri) {
      const content = await FileSystem.readAsStringAsync(asset.localUri);
      piDigitsCache = content;
      return content;
    }
  } catch (err) {
    console.error("Failed to load pi_digits.txt:", err);
  }

  const fallback =
    "";
  piDigitsCache = fallback;
  return fallback;
}

export function extractPiDigits(piString: string, startIndex: number, count: number): number[] {
  const digits: number[] = [];
  for (let i = 0; i < count; i++) {
    const idx = (startIndex + i) % piString.length;
    digits.push(parseInt(piString[idx], 10));
  }
  return digits;
}

export interface PiCoordinates {
  x: number;
  y: number;
  zoomFactor: number;
  jitterDigits: number[];
}

export function mapDigitsToCoordinates(digits30: number[]): PiCoordinates {
  const xDigits = digits30.slice(0, 10);
  const yDigits = digits30.slice(10, 20);
  const zoomDigits = digits30.slice(20, 25);
  const jitterDigits = digits30.slice(25, 30);

  const xRaw = parseInt(xDigits.join(""), 10);
  const yRaw = parseInt(yDigits.join(""), 10);
  const zoomRaw = parseInt(zoomDigits.join(""), 10);

  const x = (xRaw / 9999999999) * 4.0 - 2.0;
  const y = (yRaw / 9999999999) * 4.0 - 2.0;

  const zoomExponent = 1 + (zoomRaw / 99999) * 11;
  const zoomFactor = Math.pow(10, zoomExponent);

  return { x, y, zoomFactor, jitterDigits };
}
